"""Contact sheet for substitute teachers."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def contact_rows(students: list[Student]) -> list[str]:
    """Rows of name, section and email, sorted by name."""
    if not students:
        raise ProjectError("no students for contact sheet")
    for item in students:
        if not item.email:
            raise ProjectError(
                f"no email for {item.display_name}"
            )
    rows = sorted(
        students, key=lambda item: item.display_name
    )
    width = max(len(item.display_name) for item in rows)
    return [
        f"{item.display_name:<{width}}  "
        f"{item.section:<8}  {item.email}"
        for item in rows
    ]

